import requests, re, xml.etree.ElementTree as ET
from email.utils import parsedate_to_datetime
from datetime import datetime, timezone, timedelta

UA='Mozilla/5.0 (compatible; OpenClawScout/1.0)'
feeds={
'CoinDesk':'https://www.coindesk.com/arc/outboundfeeds/rss/',
'CoinTelegraph':'https://cointelegraph.com/rss',
'Decrypt':'https://decrypt.co/feed',
'Google News':'https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en',
'BeInCrypto':'https://beincrypto.com/feed/',
'The Block':'https://www.theblock.co/rss.xml',
'CryptoSlate':'https://cryptoslate.com/feed/',
'CryptoFox Markets':'https://cryptofox.news/rss/markets/',
'CryptoFox Regulation':'https://cryptofox.news/rss/regulation/',
}
cutoff=datetime.now(timezone.utc)-timedelta(hours=24)

def children_text(el, names):
    for c in el:
        tag=c.tag.split('}')[-1].lower()
        if tag in names and c.text:
            return c.text.strip()
    return None

for name,url in feeds.items():
    print(f'\n## {name}')
    try:
        r=requests.get(url,headers={'User-Agent':UA},timeout=18)
        print('status',r.status_code,'len',len(r.text))
        xml=r.text
        if not xml.strip():
            print('(empty)'); continue
        root=ET.fromstring(xml)
        items=[]
        for item in root.iter():
            tag=item.tag.split('}')[-1].lower()
            if tag in ('item','entry'):
                title=children_text(item, {'title'}) or ''
                link=children_text(item, {'link'}) or item.attrib.get('href','')
                pub=children_text(item, {'pubdate','published','updated'})
                dt=None
                if pub:
                    try:
                        dt=parsedate_to_datetime(pub)
                        if dt.tzinfo is None: dt=dt.replace(tzinfo=timezone.utc)
                    except Exception:
                        dt=None
                if dt and dt < cutoff:
                    continue
                if title:
                    items.append((dt,title,link))
        for dt,title,link in items[:10]:
            print('-',dt.isoformat() if dt else 'NO_DATE','|',re.sub(r'\s+',' ',title),'|',link)
        if not items:
            print('(no recent items parsed)')
    except Exception as e:
        print('ERROR',e)
PY
